const routeZeroTrafficHours = `-- name: RouteZeroTrafficHours :many
SELECT e.id AS entry_id, e.node_id, e.route_id::bigint AS route_id,
       COALESCE((SELECT sum(up + down) FROM forward_traffic_hourly t JOIN forwards f ON f.id = t.forward_id
                 WHERE f.entry_id = e.id AND f.hop = 0 AND t.hour >= $1::timestamptz), 0)::bigint AS relay_bytes,
       COALESCE((SELECT sum(up + down) FROM node_traffic_daily d
                 WHERE d.node_id = e.node_id AND d.day >= $1::timestamptz::date), 0)::bigint AS node_bytes
FROM node_entries e
WHERE e.enabled AND e.route_id IS NOT NULL AND e.created_at < $1::timestamptz
  AND EXISTS (SELECT 1 FROM forwards f WHERE f.entry_id = e.id AND f.mode <> 'manual')
`

