const setMachineState = `-- name: SetMachineState :one
UPDATE machines SET state = $1, state_changed_at = now()
FROM (SELECT o.id, o.state FROM machines o WHERE o.id = $2::bigint FOR UPDATE) AS prev
WHERE machines.id = prev.id AND prev.state <> $1
RETURNING prev.state AS previous_state
`

type SetMachineStateParams struct {
	State string
	ID    int64
}

// 只在状态变化时更新，返回变化前的状态；没有变化时不返回行。
func (q *Queries) SetMachineState(ctx context.Context, arg SetMachineStateParams) (string, error) {
	row := q.db.QueryRow(ctx, setMachineState, arg.State, arg.ID)
	var previous_state string
	err := row.Scan(&previous_state)
	return previous_state, err
}

