const usedForwardPorts = `-- name: UsedForwardPorts :many
SELECT listen_port FROM forwards WHERE machine_id = $1
`

func (q *Queries) UsedForwardPorts(ctx context.Context, machineID int64) ([]int32, error) {
	rows, err := q.db.Query(ctx, usedForwardPorts, machineID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []int32{}
	for rows.Next() {
		var listen_port int32
		if err := rows.Scan(&listen_port); err != nil {
			return nil, err
		}
		items = append(items, listen_port)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
